// Copies the tesseract.js worker and its LSTM-only WebAssembly cores from
// node_modules into public/tesseract/, so on-device OCR (src/ai/ocr.ts)
// loads them SAME-ORIGIN — the app's CSP allows no CDN — and works offline.
// public/tesseract/ is git-ignored and regenerated by predev/prebuild.
// Language data (heb/eng, tessdata_fast) is fetched on first use from
// raw.githubusercontent.com and cached by the browser.
import { copyFileSync, existsSync, mkdirSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const nm = join(here, "..", "node_modules");
const outDir = join(here, "..", "public", "tesseract");
const FILES = [
  ["tesseract.js/dist/worker.min.js", "worker.min.js"],
  ["tesseract.js-core/tesseract-core-lstm.wasm.js", "tesseract-core-lstm.wasm.js"],
  ["tesseract.js-core/tesseract-core-simd-lstm.wasm.js", "tesseract-core-simd-lstm.wasm.js"],
  ["tesseract.js-core/tesseract-core-relaxedsimd-lstm.wasm.js", "tesseract-core-relaxedsimd-lstm.wasm.js"],
];

if (!existsSync(join(nm, "tesseract.js"))) {
  console.warn("copy-tesseract: tesseract.js not installed — on-device OCR will be unavailable");
  process.exit(0);
}
mkdirSync(outDir, { recursive: true });
let total = 0;
for (const [from, to] of FILES) {
  const src = join(nm, from);
  if (!existsSync(src)) {
    console.warn(`copy-tesseract: ${from} missing`);
    continue;
  }
  const dest = join(outDir, to);
  if (!existsSync(dest) || statSync(dest).size !== statSync(src).size) copyFileSync(src, dest);
  total += statSync(src).size;
}
console.log(`copy-tesseract: ${FILES.length} files → public/tesseract/ (${(total / 1e6).toFixed(1)} MB)`);
